import random

def is_graceful(labels, num_cliques=8):
    if len(set(labels)) != 24:
        return False
    if any(l < 0 or l > 45 for l in labels):
        return False

    edge_labels = set()

    # Within cliques
    for g in range(num_cliques):
        v0 = labels[g*3 + 0]
        v1 = labels[g*3 + 1]
        v2 = labels[g*3 + 2]

        for u, v in [(v0, v1), (v1, v2), (v2, v0)]:
            diff = abs(u - v)
            if diff in edge_labels or diff == 0:
                return False
            edge_labels.add(diff)

    # Between cliques
    for g in range(num_cliques - 1):
        for i in range(3):
            u = labels[g*3 + i]
            v = labels[(g+1)*3 + i]
            diff = abs(u - v)
            if diff in edge_labels or diff == 0:
                return False
            edge_labels.add(diff)

    return len(edge_labels) == 45

def simulated_annealing(max_iter=1000000):
    # Start with a random selection of 24 labels from 0..45
    labels = random.sample(range(46), 24)

    def get_conflicts(current_labels):
        edge_labels = set()
        conflicts = 0

        # Within cliques
        for g in range(8):
            v0 = current_labels[g*3 + 0]
            v1 = current_labels[g*3 + 1]
            v2 = current_labels[g*3 + 2]
            for u, v in [(v0, v1), (v1, v2), (v2, v0)]:
                diff = abs(u - v)
                if diff in edge_labels or diff == 0:
                    conflicts += 1
                else:
                    edge_labels.add(diff)
        # Between cliques
        for g in range(7):
            for i in range(3):
                u = current_labels[g*3 + i]
                v = current_labels[(g+1)*3 + i]
                diff = abs(u - v)
                if diff in edge_labels or diff == 0:
                    conflicts += 1
                else:
                    edge_labels.add(diff)
        return conflicts

    current_labels = labels
    best_conflicts = get_conflicts(current_labels)

    import math

    temp = 1.0
    cooling_rate = 0.999995

    for i in range(max_iter):
        # Try a move
        new_labels = list(current_labels)
        if random.random() < 0.5:
            # Swap two
            idx1, idx2 = random.sample(range(24), 2)
            new_labels[idx1], new_labels[idx2] = new_labels[idx2], new_labels[idx1]
        else:
            # Replace one
            idx = random.randint(0, 23)
            new_val = random.randint(0, 45)
            if new_val in new_labels:
                continue
            new_labels[idx] = new_val

        new_conflicts = get_conflicts(new_labels)

        if new_conflicts < best_conflicts or random.random() < math.exp((best_conflicts - new_conflicts) / temp):
            current_labels = new_labels
            best_conflicts = new_conflicts
            if best_conflicts == 0:
                return current_labels

        temp *= cooling_rate
        if i % 100000 == 0:
            print(f"Iteration {i}, conflicts: {best_conflicts}, temp: {temp}")

    return None

