def local_search(max_restarts=100):
    for _ in range(max_restarts):
        labels = random.sample(range(46), 24)
        best_conflicts = get_conflicts(labels)

        for _ in range(10000):
            # Try to improve
            idx = random.randint(0, 23)
            old_val = labels[idx]

            # Try a few random values
